// TestUpsertBatch_KeysWebhooksMessagesByChildAndParent verifies dependent
// sub-collection rows with the same child id but different parent ids do not
// overwrite one another in either the generic resources table or the typed
// table. Regression for issue #2471.
func TestUpsertBatch_KeysWebhooksMessagesByChildAndParent(t *testing.T) {
	dbPath := filepath.Join(t.TempDir(), "data.db")
	s, err := Open(dbPath)
	if err != nil {
		t.Fatalf("open: %v", err)
	}
	defer s.Close()

	items := []json.RawMessage{
		json.RawMessage(`{"id": "shared_child", "webhooks_id": "parent_A"}`),
		json.RawMessage(`{"id": "shared", "webhooks_id": "child_parent_A"}`),
		json.RawMessage(`{"id": "shared_child", "webhooks_id": "parent_B"}`),
		json.RawMessage(`{"id": "other_child", "webhooks_id": "parent_A"}`),
	}
	stored, extractFailures, err := s.UpsertBatch("webhooks_messages", items)
	if err != nil {
		t.Fatalf("UpsertBatch: %v", err)
	}
	if stored != len(items) {
		t.Fatalf("stored = %d, want %d", stored, len(items))
	}
	if extractFailures != 0 {
		t.Fatalf("extractFailures = %d, want 0", extractFailures)
	}

	db := s.DB()

	var generic int
	if err := db.QueryRow(`SELECT COUNT(*) FROM resources WHERE resource_type = ?`, "webhooks_messages").Scan(&generic); err != nil {
		t.Fatalf("count resources: %v", err)
	}
	if generic != len(items) {
		t.Fatalf("resources count = %d, want %d (dependent rows collapsed on child id)", generic, len(items))
	}

	var typed int
	typedQuery := fmt.Sprintf(`SELECT COUNT(*) FROM "%s"`, "webhooks_messages")
	if err := db.QueryRow(typedQuery).Scan(&typed); err != nil {
		t.Fatalf("count webhooks_messages: %v", err)
	}
	if typed != len(items) {
		t.Fatalf("webhooks_messages count = %d, want %d (typed rows collapsed on child id)", typed, len(items))
	}

	var parentMatches int
	parentQuery := fmt.Sprintf(`SELECT COUNT(*) FROM "%s" WHERE "webhooks_id" = ?`, "webhooks_messages")
	if err := db.QueryRow(parentQuery, "parent_A").Scan(&parentMatches); err != nil {
		t.Fatalf("count by webhooks_id: %v", err)
	}
	if parentMatches != 2 {
		t.Fatalf("webhooks_id=parent_A count = %d, want 2", parentMatches)
	}
}

